/* From Uiverse.io by vinodjangid07 - Tags: input, Microphone, search, search bar */
.__UIV_SCOPE__ .InputContainer {
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgb(255, 255, 255);
  border-radius: 10px;
  overflow: hidden;
  cursor: pointer;
  padding-left: 15px;
  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.075);
}

.__UIV_SCOPE__ .input {
  width: 170px;
  height: 100%;
  border: none;
  outline: none;
  font-size: 0.9em;
  caret-color: rgb(255, 81, 0);
}

.__UIV_SCOPE__ .labelforsearch {
  cursor: text;
  padding: 0px 12px;
}

.__UIV_SCOPE__ .searchIcon {
  width: 13px;
}

.__UIV_SCOPE__ .border {
  height: 40%;
  width: 1.3px;
  background-color: rgb(223, 223, 223);
}

.__UIV_SCOPE__ .micIcon {
  width: 12px;
}

.__UIV_SCOPE__ .micButton {
  padding: 0px 15px 0px 12px;
  border: none;
  background-color: transparent;
  height: 40px;
  cursor: pointer;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .searchIcon path {
  fill: rgb(114, 114, 114);
}

.__UIV_SCOPE__ .micIcon path {
  fill: rgb(255, 81, 0);
}

.__UIV_SCOPE__ .micButton:hover {
  background-color: rgb(255, 230, 230);
  transition-duration: .3s;
}
